import{_ as e,c as o,o as r,af as l,ar as t,as as i}from"./chunks/framework.CI8A52oi.js";const m=JSON.parse('{"title":"RWP新手指南","description":"","frontmatter":{},"headers":[],"relativePath":"noew.md","filePath":"noew.md"}'),n={name:"noew.md"};function s(c,a,d,p,h,g){return r(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="rwp新手指南" tabindex="-1"><strong>RWP新手指南</strong> <a class="header-anchor" href="#rwp新手指南" aria-label="Permalink to “RWP新手指南”">​</a></h1><blockquote><p>credit by Neko_Annieawa</p></blockquote><h2 id="x-目录" tabindex="-1">X.目录： <a class="header-anchor" href="#x-目录" aria-label="Permalink to “X.目录：”">​</a></h2><ul><li><a href="#i-如何使用java版加入服务器">I.如何使用Java版加入服务器</a></li><li><a href="#ii-与服务器相关的一些指令哦">II.与服务器相关的一些指令哦</a></li><li><a href="#iii-与服务器相关的特性">III.与服务器相关的特性</a></li></ul><h2 id="i-如何使用java版加入服务器" tabindex="-1">I.<strong>如何使用Java版加入服务器</strong> <a class="header-anchor" href="#i-如何使用java版加入服务器" aria-label="Permalink to “I.如何使用Java版加入服务器”">​</a></h2><ul><li>如果您对Java版感到疑惑请参阅<a href="//doc.samuge.red/diffmc" target="_blank" rel="noreferrer">此链接</a></li><li>如果您使用基岩版，登录微软账户之后可直接填写服务器信息游玩，相应教程后续更新</li></ul><h3 id="请参阅以下文档喵" tabindex="-1">请参阅以下文档喵！ <a class="header-anchor" href="#请参阅以下文档喵" aria-label="Permalink to “请参阅以下文档喵！”">​</a></h3><p>​ <strong><a href="//doc.samuge.red/regisbs" target="_blank" rel="noreferrer">如何注册服务器</a></strong></p><hr><h2 id="ii-与服务器相关的一些指令哦" tabindex="-1">II.与服务器相关的一些指令哦 <a class="header-anchor" href="#ii-与服务器相关的一些指令哦" aria-label="Permalink to “II.与服务器相关的一些指令哦”">​</a></h2><p><strong>注意：你完全没有必要仔细阅读以下的所有内容，可以先了解大致纲要，在游玩中实验哦</strong></p><h3 id="_1-关于地标" tabindex="-1">1. <strong>关于地标</strong> <a class="header-anchor" href="#_1-关于地标" aria-label="Permalink to “1. 关于地标”">​</a></h3><ul><li><p>使用<code>/warplist</code>可以打开地标列表</p></li><li><p>使用<code>/setwarp [名字]</code>可以设定地标</p></li><li><p>使用<code>/warp [名字]</code>可以直接传送到某地标</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>有几个服务器地标哦：商城，抽奖屋，长街</strong></p><p><strong>商城：</strong>和想象中的不同，它是收购东西的地方<em>（你可以在这里通过卖菜和卖矿物来赚钱x）</em></p><p><strong>抽奖屋：</strong>这里可以进行服务器的<strong>酒谱抽奖呐，</strong>关于服务器酿酒这一特色玩法参见<a href="https://docs.qq.com/doc/DYWR4S0N1Z1JYTGdu" target="_blank" rel="noreferrer">关于酿酒</a>哦</p><p><strong>长街：</strong>这里是市集！可以买矿物，染料等，甚至还有鞘翅和三叉戟<em>（当然非常黑）</em></p><p><strong>另外还有许许多多玩家地标建议去探索呢！</strong></p><p><strong><code>center-headquarters</code>（中央指挥部，历经四年仍然坚挺）</strong></p><p><strong><code>center-revoluntionary</code>（革命起事之地，隶属于共产国际）</strong></p><p><strong><code>cherry_island</code> (Sakura Island樱花岛，也是玩家聚集地喵)</strong></p><p><strong><code>mooncake_shop</code> (猫猫的月饼铺子（划掉），节日限定x)</strong></p><p>还有许多机器所在的功能性地标，这里就不赘述啦~</p></div></li></ul><h3 id="_2-关于家" tabindex="-1">2. <strong>关于家</strong> <a class="header-anchor" href="#_2-关于家" aria-label="Permalink to “2. 关于家”">​</a></h3><ul><li>使用<code>/sethome [名字]</code>可以设定家</li><li>使用<code>/home [名字]</code>可以传送到家</li><li>使用<code>/homelist</code>可以设定家列表</li></ul><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p></p><p><strong>注意哦，地标和家的设置都是有上限的</strong>（前者4个，后者3个），要珍惜分配使用喵</p></div><h3 id="_3-关于礼包" tabindex="-1">3. <strong>关于礼包</strong> <a class="header-anchor" href="#_3-关于礼包" aria-label="Permalink to “3. 关于礼包”">​</a></h3><ul><li>使用<code>/kitlist</code>可以打开礼包列表</li></ul><h3 id="_4-关于公会" tabindex="-1">4. <strong>关于公会</strong> <a class="header-anchor" href="#_4-关于公会" aria-label="Permalink to “4. 关于公会”">​</a></h3><ul><li>参阅链接<a href="https://docs.qq.com/doc/DYVd1T2xTSkdTVFVC?no_promotion=1" target="_blank" rel="noreferrer">关于公会（施工中）</a></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>以上所有功能皆可在<code>/mainmenu</code>中打开相关功能，无需记住全部指令</strong></p></div><h3 id="_5-关于传送" tabindex="-1">5. <strong>关于传送</strong> <a class="header-anchor" href="#_5-关于传送" aria-label="Permalink to “5. 关于传送”">​</a></h3><ul><li>玩家可以使用<code>/tpa [玩家名]</code>向指定玩家发送请求</li><li>使用<code>/tphere [玩家名]</code>可以请求指定玩家传送到此处</li></ul><h3 id="_6-关于商店" tabindex="-1">6. <strong>关于商店</strong> <a class="header-anchor" href="#_6-关于商店" aria-label="Permalink to “6. 关于商店”">​</a></h3><p>玩家可以手持物品，左键点击箱子，并在物品栏里输入价格，即可创建属于自己的商店</p><ul><li><p>使用<code>/qs sell</code>可以将商店设为出售模式</p></li><li><p>使用<code>/qs buy</code>可以将商店设为收购模式</p></li><li><p>使用<code>/qs remove</code>可以删除此商店</p></li><li><p>使用<code>/qs price</code>可以修改单价</p><blockquote><p>其实作为商店的所有者……右键告示牌就可以很方便配置啦owo</p></blockquote></li></ul><h3 id="_7-关于金钱系统" tabindex="-1">7. 关于金钱系统 <a class="header-anchor" href="#_7-关于金钱系统" aria-label="Permalink to “7. 关于金钱系统”">​</a></h3><blockquote><p>你知道吗，传说每到疯狂星期四都可以找腐竹v你50RWB（注意是RWB）</p></blockquote><p>​ 金钱属于是很多服务器的标配了叭，本服也不例外哦</p><p>​ 但是本服作为公益服，保证所有金钱都可以通过卖菜和卖矿获得x</p><p>​ 获得的金钱可以通过箱子商店和玩家作交易，或者在长街购买道具，购买酒谱抽奖钥匙<em>（但是千万不要盲目抽卡……）</em></p><ul><li>使用<code>/baltop 或 /balancetop</code>来查看金钱排行榜</li><li>使用<code>/pay [玩家名] [数额]</code>来向一名在线玩家付钱</li></ul><h3 id="_8-关于酿酒" tabindex="-1">8. <strong>关于酿酒</strong> <a class="header-anchor" href="#_8-关于酿酒" aria-label="Permalink to “8. 关于酿酒”">​</a></h3><blockquote><p>酿酒是本服务器的特色玩法之一呐！可以方便地为养老生存提供一点新奇的乐趣……（）</p></blockquote><p>​ 请参阅<a href="./关于酿酒.html">关于酿酒</a>喵</p><h3 id="_9-关于领地" tabindex="-1">9. 关于领地 <a class="header-anchor" href="#_9-关于领地" aria-label="Permalink to “9. 关于领地”">​</a></h3><p>玩家持有箭矢物品，通过左键和右键分别选取点，划分自己的领地范围：</p><ul><li>面板指令：<code>/dominion</code></li><li>创建领地：<code>/dominion create [名称]</code></li></ul><hr><h2 id="iii-与服务器相关的特性" tabindex="-1">III.与服务器相关的特性 <a class="header-anchor" href="#iii-与服务器相关的特性" aria-label="Permalink to “III.与服务器相关的特性”">​</a></h2><h3 id="_1-关于插件" tabindex="-1">1. 关于插件 <a class="header-anchor" href="#_1-关于插件" aria-label="Permalink to “1. 关于插件”">​</a></h3><p>服务器现在装载了其它一些插件/扩展玩法，但基本不影响原版生存哦~，显性的玩法插件有：</p><ul><li><strong>技能系统：</strong>通过游戏内行为获取经验，然后升级对应技能，让自己变得更强大（</li><li><strong>附魔扩展：</strong>多了许许多多奇奇怪怪的小附魔，优化生存体验</li><li><strong>酿酒插件：</strong>好喝！</li></ul><h3 id="_2-关于红石" tabindex="-1">2. 关于红石 <a class="header-anchor" href="#_2-关于红石" aria-label="Permalink to “2. 关于红石”">​</a></h3><p>服务器搭载了红石线优化模组，这使得服务器对高频电路具有一定抗性，对红石没有限制x</p><p>但是这也导致<strong>大部分三无TNT复制</strong>及依赖<strong>红石线bud</strong>的装置失效，请注意</p><ul><li><a href="https://www.mcmod.cn/class/7121.html" target="_blank" rel="noreferrer">优化模组点此</a></li></ul><h3 id="_3-关于交互" tabindex="-1">3. 关于交互 <a class="header-anchor" href="#_3-关于交互" aria-label="Permalink to “3. 关于交互”">​</a></h3><p>服务器通过插件实现了利用<code>&amp;</code>代替<code>§</code>打出颜色文本的方法，所以可以在聊天框以及铁砧内……嘻嘻嘻</p><h3 id="_4-关于我们" tabindex="-1">4. 关于我们 <a class="header-anchor" href="#_4-关于我们" aria-label="Permalink to “4. 关于我们”">​</a></h3><p>红白阁的大家都是非常<strong>友善且热情的！</strong>只要你想要加入我们，愿意和我们一起玩，我们随时欢迎你加入红白阁的大家庭！</p><p><img src="'+t+'" alt=""></p><blockquote><p>大合照（摄于2025.8.27）</p></blockquote><p><img src="'+i+'" alt=""></p><blockquote><p>现在是2025年10月17日的凌晨1点07分。</p><p>来自猫猫 Neko_Annieawa 的祝福</p><p>愿你在RWP找到好的伙伴。</p><p>谨此</p></blockquote>',55)])])}const _=e(n,[["render",s]]);export{m as __pageData,_ as default};
